/* eu-icons.js — BETA-06
 * Iconos de la UE embebidos como base64 para funcionamiento en file://
 * y entornos sin servidor. Los archivos originales siguen presentes en
 * assets/eu-icons/ para uso externo.
 *
 * Correspondencia mecánica y automática entre el `type` declarado en el
 * bloque PTC DISCLOSURE (DCL-03) y el icono oficial de la UE.
 * Esto NUNCA determina obligación jurídica.
 */
const PTCEuIcons = (() => {

  const TYPE_TO_ICON = {
    ai_generated: 'fully-ai-generated',
    ai_modified: 'partially-ai-modified',
    ai_generated_or_modified: 'basic',
  };

  function iconIdForType(type) {
    return TYPE_TO_ICON[type] || null;
  }

  const DEFAULT_VARIANTS = ['black', 'white'];

  // Datos inline — funcionan desde file:// sin fetch()
  const ICON_DATA = {
    'basic': {
      black_svg: '',
      black_png: '',
      white_svg: '',
      white_png: '',
    },
    'fully-ai-generated': {
      black_svg: '',
      black_png: '',
      white_svg: '',
      white_png: '',
    },
    'partially-ai-modified': {
      black_svg: '',
      black_png: '',
      white_svg: '',
      white_png: '',
    },
  };

  function b64ToArrayBuffer(b64) {
    const bin = atob(b64);
    const buf = new ArrayBuffer(bin.length);
    const u8 = new Uint8Array(buf);
    for (let i = 0; i < bin.length; i++) u8[i] = bin.charCodeAt(i);
    return buf;
  }

  // Retorna ArrayBuffers listos para usar (sin fetch, sin red, sin servidor)
  function getIconData(iconId) {
    const d = ICON_DATA[iconId];
    if (!d) return null;
    return {
      black_svg: b64ToArrayBuffer(d.black_svg),
      black_png: b64ToArrayBuffer(d.black_png),
      white_svg: b64ToArrayBuffer(d.white_svg),
      white_png: b64ToArrayBuffer(d.white_png),
    };
  }

  function assetPaths(iconId, basePath = 'assets/eu-icons') {
    const paths = {};
    DEFAULT_VARIANTS.forEach(variant => {
      paths[variant] = {
        svg: `${basePath}/svg/${iconId}_${variant}.svg`,
        png: `${basePath}/png/${iconId}_${variant}.png`,
      };
    });
    return paths;
  }

  return { TYPE_TO_ICON, iconIdForType, DEFAULT_VARIANTS, assetPaths, getIconData };
})();

if (typeof window !== 'undefined') window.PTCEuIcons = PTCEuIcons;